import{_ as i,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-05-01 :: Ceph Developer Meeting","description":"","frontmatter":{"title":"2019-05-01 :: Ceph Developer Meeting","date":"2019-05-01T00:00:00.000Z","updated":"2019-05-14T00:00:00.000Z","tags":["Ceph","Distributed Storage","Monitor Election","Multi","Data Center Testing","Memory Target Setting","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-01_-_-_Ceph_Developer_Meeting.md","filePath":"posts/2019/2019-05-01_-_-_Ceph_Developer_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-05-01_-_-_Ceph_Developer_Meeting.md"};function p(s,l,n,a,_,g){return e(),t("div",null,[...l[0]||(l[0]=[o("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Brad、Sofia、Sridhar 等</p><p><strong>会议主题</strong>：</p><ul><li>多数据中心测试</li><li>监视器选举策略</li><li>内存目标设置</li><li>监视器性能优化</li></ul><p><strong>关键细节与讨论议题</strong>：</p><ol><li><p><strong>多数据中心测试</strong>：</p><ul><li>讨论了通过iptables进行多数据中心测试的进展，模拟网络故障。</li><li>讨论了监视器在故障情况下的内存使用策略，包括如何映射故障到CRUSH map，以及如何处理选举过程中的故障。</li><li>认为在选举过程中，监视器应基于其连接的节点数量排序，选择连接节点数量最多的监视器作为领导者。</li></ul></li><li><p><strong>监视器选举策略</strong>：</p><ul><li>讨论了监视器选举策略的优化，包括如何处理网络故障、延迟和可靠性问题。</li><li>认为应设置每个监视器的可靠性分数，并根据连接数量、延迟和可靠性等因素计算总分。</li><li>讨论了通过选举消息共享信息，以及如何确保信息的一致性。</li></ul></li><li><p><strong>内存目标设置</strong>：</p><ul><li>讨论了内存目标设置的进展，包括RocksDB和OSD map cache的内存分配。</li><li>讨论了如何根据缓存大小和性能需求调整内存分配。</li></ul></li><li><p><strong>监视器性能优化</strong>：</p><ul><li>讨论了监视器性能优化的方法，包括提高连接数量、降低延迟和提升可靠性。</li><li>认为应通过增加监视器副本数量来提高可靠性，并确保监视器副本均匀分布在不同的数据中心。</li></ul></li></ol><p><strong>决定的事项</strong>：</p><ol><li>完成多数据中心测试，并分析测试结果。</li><li>优化监视器选举策略，包括设置可靠性分数和计算总分。</li><li>调整内存目标设置，确保缓存大小和性能需求得到满足。</li><li>进一步研究监视器性能优化方法，并实施相应的改进措施。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Sofia将编写测试脚本，模拟网络故障，并分析测试结果。</li><li>Brad将优化监视器选举策略，并实现相应的代码。</li><li>Sridhar将调整内存目标设置，并确保缓存大小和性能需求得到满足。</li><li>团队将共同研究监视器性能优化方法，并实施相应的改进措施。</li></ol><p><strong>改进点</strong>：</p><ul><li>确保了Ceph相关领域的英文关键词被保留。</li><li>明确了多数据中心测试的细节，包括使用iptables模拟网络故障。</li><li>精细化了监视器选举策略的讨论，包括设置可靠性分数和计算总分。</li><li>增加了内存目标设置的细节，包括RocksDB和OSD map cache的内存分配。</li><li>强调了监视器性能优化的方法，包括提高连接数量、降低延迟和提升可靠性。</li></ul>",13)])])}const u=i(r,[["render",p]]);export{d as __pageData,u as default};
